const MONTH_ABBR = ["","Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"] as const;

interface SeasonScore {
  event:        SeasonEvent | null;   // best-matching event
  timing:       number;               // 0-100 — how well publish week aligns with event peak
  monthsOff:    number;               // months away from nearest peak month
  tier:         "perfect" | "good" | "suboptimal" | "mistimed" | "evergreen";
  isEvergreen:  boolean;
  publishMonth: number;               // 1-12
}

function scoreSeasonality(e: { topic: string; angle: string; week: number }): SeasonScore {
  const hay          = `${e.topic} ${e.angle}`.toLowerCase();
  const publishMonth = Math.min(12, Math.max(1, Math.ceil(e.week / 4.33)));

  // Find the event with the most keyword hits
  let bestEvent: SeasonEvent | null = null;
  let bestHits = 0;
  for (const ev of SEASON_EVENTS) {
    const hits = ev.keywords.filter((k) => hay.includes(k)).length;
    if (hits > bestHits) { bestHits = hits; bestEvent = ev; }
  }

  if (!bestEvent || bestHits === 0) {
    return { event: null, timing: 50, monthsOff: 0, tier: "evergreen", isEvergreen: true, publishMonth };
  }

  // Distance from publish month to nearest peak month (circular)
  const dist = bestEvent.months.reduce((min, m) => {
    const d = Math.min(Math.abs(publishMonth - m), 12 - Math.abs(publishMonth - m));
    return Math.min(min, d);
  }, 99);

  const timing  = dist === 0 ? 100 : dist === 1 ? 72 : dist === 2 ? 44 : dist === 3 ? 20 : 5;
  const tier    = timing >= 80 ? "perfect" : timing >= 55 ? "good" : timing >= 30 ? "suboptimal" : "mistimed";

  return { event: bestEvent, timing, monthsOff: dist, tier, isEvergreen: false, publishMonth };
}

// ─── Content Cannibalism Detector ────────────────────────────────────────────
const CANNIBAL_STOP = new Set([
  "a","an","the","and","or","in","of","for","to","is","are","how","why","what","with",
  "that","this","your","you","on","at","by","from","as","it","its","be","can","will",
  "their","which","our","we","has","have","do","not","more","less","new","get","all",
  "into","via","vs","using","across","through","within","between","around","about",
  "over","under","up","top","key","most","best","every","each","should","could","when",
  "while","whether","if","then","also","even","just","only","both","many","some","any",
]);

function cannibalTokens(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, " ")
    .split(/\s+/)
    .filter((w) => w.length > 2 && !CANNIBAL_STOP.has(w));
}

function cannibalScore(
  a: { type: ContentType; topic: string; angle: string },
  b: { type: ContentType; topic: string; angle: string },
): { score: number; shared: string[] } {
  const tokA = new Set(cannibalTokens(`${a.topic} ${a.angle}`));
  const tokB = new Set(cannibalTokens(`${b.topic} ${b.angle}`));
  const union = new Set([...tokA, ...tokB]);
  const shared = [...tokA].filter((t) => tokB.has(t));
  const jaccard = union.size > 0 ? shared.length / union.size : 0;
  let score = Math.round(jaccard * 75);
  if (a.type === b.type) score = Math.min(100, score + 15);
  return { score, shared };
}

interface CannibalPair {
  a:      ReturnType<typeof Object.assign> & { type: ContentType; topic: string; angle: string; week: number; date: string };
  b:      ReturnType<typeof Object.assign> & { type: ContentType; topic: string; angle: string; week: number; date: string };
  score:  number;
  shared: string[];
  severity: "critical" | "high" | "moderate";
}

// ─── Revenue Attribution Modeller ────────────────────────────────────────────
const RA_TOFU_SIGNALS     = ["what is","introduction","overview","trends","state of","guide to","understanding","101","primer","landscape","ecosystem","rise of","evolution of","history of","future of","impact of","emergence of","growth of"];
const RA_MOFU_SIGNALS     = ["how to choose","comparison","vs ","alternative","benchmark","best practice","framework","strategy","approach","roadmap","checklist","template","playbook","model","methodology","evaluate","assess","select","optimise","optimize","improve","consider","build"];
const RA_BOFU_SIGNALS     = ["case study","roi","results","outcome","implementation","migration","vendor","pricing","demo","proof","client","customer","success story","before and after","transformation","saved","grew","reduced by","increased by","achieved","delivered","generated","cut","won"];
const RA_ENTERPRISE_SIG   = ["enterprise","tier 1 bank","financial institution","c-suite","cfo","cto","chief","head of","director of","vp ","institutional","global bank","investment bank","wealth management","asset manager","central bank","regulator","board level"];
const RA_MIDMARKET_SIG    = ["fintech","scale-up","growth stage","series b","series c","mid-market","regional bank","credit union","challenger bank","digital bank","payments provider","lending platform","insurtech","wealthtech","neobank"];

type FunnelStage = "TOFU" | "MOFU" | "BOFU";

const BASE_LEADS: Record<ContentType, number> = {
  "guide":      0.8,
  "case-study": 2.5,
  "blog":       0.3,
  "roundup":    0.2,
  "linkedin":   0.4,
};

const RA_DEAL_SIZE: Record<"enterprise" | "mid-market" | "smb", number> = {
  enterprise:    85000,
  "mid-market":  25000,
  smb:           8000,
};

const STAGE_MULT: Record<FunnelStage, number> = {
  BOFU: 1.0,
  MOFU: 0.6,
  TOFU: 0.3,
};

const TYPE_STAGE_PRIOR: Record<ContentType, FunnelStage> = {
  guide:         "TOFU",
  blog:          "TOFU",
  roundup:       "TOFU",
  "case-study":  "BOFU",
  linkedin:      "MOFU",
};

interface RAEntry {
  stage:     FunnelStage;
  buyerTier: "enterprise" | "mid-market" | "smb";
  baseLeads: number;
  pipeline:  number;
  stageFlag: boolean;
}

function scoreRA(e: { type: ContentType; topic: string; angle: string }): RAEntry {
  const hay       = `${e.topic} ${e.angle}`.toLowerCase();
  const tofuHits  = RA_TOFU_SIGNALS.filter((s) => hay.includes(s)).length;
  const mofuHits  = RA_MOFU_SIGNALS.filter((s) => hay.includes(s)).length;
  const bofuHits  = RA_BOFU_SIGNALS.filter((s) => hay.includes(s)).length;
  const stage: FunnelStage =
    bofuHits > 0                       ? "BOFU" :
    mofuHits > 0 && mofuHits >= tofuHits ? "MOFU" :
    tofuHits > 0                       ? "TOFU" :
    TYPE_STAGE_PRIOR[e.type];
  const isEnterprise = RA_ENTERPRISE_SIG.some((s) => hay.includes(s));
  const isMidMarket  = RA_MIDMARKET_SIG.some((s) => hay.includes(s));
  const buyerTier: RAEntry["buyerTier"] = isEnterprise ? "enterprise" : isMidMarket ? "mid-market" : "smb";
  const baseLeads = BASE_LEADS[e.type];
  const pipeline  = Math.round(baseLeads * RA_DEAL_SIZE[buyerTier] * STAGE_MULT[stage]);
  const stageFlag = (stage === "BOFU" && (e.type === "linkedin" || e.type === "roundup"))
                 || (stage === "TOFU" && e.type === "case-study");
  return { stage, buyerTier, baseLeads, pipeline, stageFlag };
}

function fmtPipeline(v: number): string {
  if (v >= 1_000_000) return `£${(v / 1_000_000).toFixed(1)}M`;
  if (v >= 1_000)     return `£${Math.round(v / 1_000)}K`;
  return `£${v}`;
}

// ─── Content Velocity Tracker ────────────────────────────────────────────────
const BASE_TIME_TO_PEAK: Record<ContentType, number | null> = {
  "guide":      5,    // months to first meaningful organic traffic
  "case-study": 3.5,
  "blog":       5,
  "roundup":    3,
  "linkedin":   null, // social-only, no SEO compounding
};

const CV_HALFLIFE: Record<ContentType, number> = {
  "guide":      18,
  "case-study": 12,
  "blog":       8,
  "roundup":    4,
  "linkedin":   1,
};

// High-competition topic signals → adds 2 months to ranking time
const CV_HIGH_COMP = ["compliance","regulation","regulatory","crypto","blockchain","payments","banking","insurance","lending","mortgage","investing","trading","tax","aml","kyc","gdpr","pci","basel","fatca","mifid","dodd-frank"];
// Niche/specialist signals → removes 1 month (less competition, faster indexing)
const CV_NICHE     = ["embedded finance","open banking","treasury","bnpl","regtech","insurtech","wealthtech","neobank","defi","stablecoin","tokenisation","paytech","suptech","clo","clm","core banking modernisation","ledger","vault","cfo tech"];

type CVTier = "fast" | "standard" | "slow" | "social-only";
type CVCompetition = "high" | "standard" | "niche";

interface CVEntry {
  timeToTraffic: number | null;
  halfLife:      number;
  mismatch:      boolean;
  competition:   CVCompetition;
  tier:          CVTier;
  publishMonth:  number;
  peakMonth:     number | null;
}

function calcVelocity(e: { type: ContentType; topic: string; angle: string; week: number }): CVEntry {
  const base     = BASE_TIME_TO_PEAK[e.type];
  const halfLife = CV_HALFLIFE[e.type];
  const hay      = `${e.topic} ${e.angle}`.toLowerCase();
  const isHigh   = CV_HIGH_COMP.some((s) => hay.includes(s));
  const isNiche  = CV_NICHE.some((s) => hay.includes(s));
  const competition: CVCompetition = isNiche ? "niche" : isHigh ? "high" : "standard";
  const publishMonth = Math.ceil(e.week / 4.33);

  if (base === null) {
    return { timeToTraffic: null, halfLife, mismatch: false, competition, tier: "social-only", publishMonth, peakMonth: null };
  }

  const adjusted   = Math.max(1, base + (isHigh ? 2 : 0) - (isNiche ? 1 : 0));
  const peakMonth  = publishMonth + adjusted;
  const mismatch   = adjusted > halfLife;
  const tier: CVTier = adjusted <= 3 ? "fast" : adjusted <= 6 ? "standard" : "slow";
  return { timeToTraffic: adjusted, halfLife, mismatch, competition, tier, publishMonth, peakMonth };
}

// ─── Thought Leadership Index ─────────────────────────────────────────────────
const TL_POV_SIGNALS       = ["predict","believe","argue","case for","perspective","our view","our take","opinion","we think","position","stance","bold","provocative","thesis","assert","contend","challenge","disagree","contrary","wrong about","time to rethink","rethinking","myth","reframe","redefine"];
const TL_CATEGORY_SIGNALS  = ["introducing","new framework","our model","our methodology","we call","coined","first to","pioneered","category","taxonomy","defined as","framework for","playbook","our approach","proprietary","original research","we built","developed by","created by","our tool"];
const TL_INSIGHT_SIGNALS   = ["counterintuitive","surprising","overlooked","underrated","nobody talks about","what most miss","hidden","rarely discussed","beneath the surface","second-order","root cause","systemic","nuanced","complex","unpopular","uncomfortable","actually","in reality","the real reason","what really"];
const TL_EVIDENCE_SIGNALS  = ["research shows","data shows","study","evidence","proven","validated","tested","measured","our clients","client data","we found","in our experience","from working with","after analysing","based on","n=","sample","tracked","monitored","over x years","in practice"];
const TL_VISION_SIGNALS    = ["future","predict","forecast","by 2025","by 2026","by 2027","next decade","next five years","emerging","paradigm shift","will change","will transform","on the horizon","coming shift","where fintech is heading","where banking is going","in ten years","long-term","strategic implication"];
const TL_COMMODITY_SIGNALS = ["what is","introduction to","overview of","basics of","beginners guide","101","getting started with","a guide to","how does","everything you need to know","what are","types of","definition of","meaning of","explained simply","for dummies","primer on"];

interface TLScore {
  total:      number;
  pov:        number;
  category:   number;
  insight:    number;
  evidence:   number;
  vision:     number;
  isCommodity: boolean;
  tier:       "leader" | "strong" | "developing" | "commodity";
  enhancements: string[];
}

function scoreTL(topic: string, angle: string): TLScore {
  const hay = `${topic} ${angle}`.toLowerCase();
  const pov      = Math.min(30, TL_POV_SIGNALS.filter((s) => hay.includes(s)).length * 10);
  const category = Math.min(25, TL_CATEGORY_SIGNALS.filter((s) => hay.includes(s)).length * 9);
  const insight  = Math.min(20, TL_INSIGHT_SIGNALS.filter((s) => hay.includes(s)).length * 7);
  const evidence = Math.min(15, TL_EVIDENCE_SIGNALS.filter((s) => hay.includes(s)).length * 6);
  const vision   = Math.min(10, TL_VISION_SIGNALS.filter((s) => hay.includes(s)).length * 5);
  const total = pov + category + insight + evidence + vision;
  const commodityHits = TL_COMMODITY_SIGNALS.filter((s) => hay.includes(s)).length;
  const isCommodity = commodityHits > 0 && total < 25;
  const tier: TLScore["tier"] = total >= 60 ? "leader" : total >= 40 ? "strong" : total >= 20 ? "developing" : "commodity";
  const enhancements: string[] = [];
  if (pov < 10)      enhancements.push("State a bold opening thesis — declare what you believe that most in the industry don't, then defend it with evidence. Opinion without a stake in the ground isn't thought leadership.");
  if (category < 8)  enhancements.push("Coin a specific term or name your framework — named models and proprietary methodologies get cited and shared far more than generic advice ('The X Framework' outperforms 'Tips for X').");
  if (insight < 7)   enhancements.push("Find the non-obvious implication — what does mainstream coverage of this topic consistently miss? Build the whole piece around that gap in the conversation.");
  if (evidence < 5)  enhancements.push("Anchor your POV in named client data, original research, or a specific case — opinion without evidence is commentary, not thought leadership that earns trust.");
  if (vision < 4)    enhancements.push("Add a 12–24 month prediction — forward-looking claims position you as a guide rather than a reporter. Specific, falsifiable predictions build authority faster than trend summaries.");
  return { total, pov, category, insight, evidence, vision, isCommodity, tier, enhancements };
}

// ─── Social Amplification Planner ────────────────────────────────────────────
const VIRAL_CONTRARIAN = ["myth","wrong","mistake","debunking","counterintuitive","unpopular","hot take","controversial","against","disagree","rethinking","uncomfortable truth","overrated","nobody talks about","stop","don't"];
const VIRAL_DATA       = ["statistic","statistics","data","study","survey","benchmark","research","found that","shows that","revealed","according to","findings","measured","tracked","reported","numbers","metric"];
const VIRAL_URGENCY    = ["risk","warning","danger","losing","missing out","critical","alert","fraud","threat","crisis","deadline","must","urgent","time-sensitive","avoid","before","costly"];
const VIRAL_ASPIRE     = ["how to","build","grow","achieve","succeed","master","become","launch","win","transform","improve","boost","scale","level up","unlock","increase","double","triple"];
const VIRAL_INSIDER    = ["insider","secret","nobody tells you","truth","behind the scenes","hidden","what they don't","actually","revealed","confession","honest","overlooked","underrated","rarely","few people"];

const ATOMISE_BY_TYPE: Record<ContentType, { count: number; breakdown: string[] }> = {
  "guide":      { count: 10, breakdown: ["5 LinkedIn posts (one insight per section)", "3 Twitter/X thread openers (one per key argument)", "2 newsletter feature sections"] },
  "case-study": { count: 7,  breakdown: ["3 LinkedIn story posts (setup / conflict / result)", "2 result-stat tweets", "1 newsletter client spotlight section", "1 trade press pitch angle"] },
  "roundup":    { count: 8,  breakdown: ["1 tweet per resource listed", "2 LinkedIn intro carousel slides", "1 newsletter 'what we're reading' section"] },
  "blog":       { count: 5,  breakdown: ["3 LinkedIn insight posts (one key takeaway each)", "1 Twitter/X thread opener", "1 newsletter teaser with CTA"] },
  "linkedin":   { count: 2,  breakdown: ["1 Twitter/X adapted version (condensed)", "1 newsletter quote or mention"] },
};

type ViralDim = "contrarian" | "data" | "urgency" | "aspire" | "insider";
interface ViralScore {
  total:      number;
  contrarian: number;
  data:       number;
  urgency:    number;
  aspire:     number;
  insider:    number;
  dominant:   ViralDim;
  tier:       "viral" | "high" | "moderate" | "low";
}

function scoreViral(topic: string, angle: string): ViralScore {
  const hay = `${topic} ${angle}`.toLowerCase();
  const contrarian = Math.min(25, VIRAL_CONTRARIAN.filter((s) => hay.includes(s)).length * 9);
  const data       = Math.min(25, VIRAL_DATA.filter((s) => hay.includes(s)).length * 9);
  const urgency    = Math.min(20, VIRAL_URGENCY.filter((s) => hay.includes(s)).length * 7);
  const aspire     = Math.min(15, VIRAL_ASPIRE.filter((s) => hay.includes(s)).length * 5);
  const insider    = Math.min(15, VIRAL_INSIDER.filter((s) => hay.includes(s)).length * 8);
  const total = contrarian + data + urgency + aspire + insider;
  const tier: ViralScore["tier"] = total >= 60 ? "viral" : total >= 40 ? "high" : total >= 20 ? "moderate" : "low";
  const dims: [ViralDim, number][] = [["contrarian", contrarian], ["data", data], ["urgency", urgency], ["aspire", aspire], ["insider", insider]];
  const dominant = dims.sort(([, a], [, b]) => b - a)[0][0];
  return { total, contrarian, data, urgency, aspire, insider, dominant, tier };
}

