function getPersona(
  topic: string,
): (typeof PERSONA_BY_NICHE)[0] {
  const lower = topic.toLowerCase();
  return (
    PERSONA_BY_NICHE.find((p) =>
      p.keywords.some((kw) => kw && lower.includes(kw)),
    ) ?? PERSONA_BY_NICHE[PERSONA_BY_NICHE.length - 1]
  );
}

